-- Additive Startup Skool public admissions records. Existing identities and
-- application records are unchanged. CUID ids are generated by Prisma Client.
CREATE TABLE "StartupPublicApplicant" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "reference" TEXT NOT NULL,
    "possessionSecretHash" TEXT NOT NULL,
    "fullName" TEXT,
    "mobile" TEXT,
    "normalizedMobile" TEXT,
    "email" TEXT,
    "state" TEXT,
    "district" TEXT,
    "preferredCentre" TEXT,
    "programPreference" TEXT,
    "entrepreneurialStage" TEXT,
    "businessInterest" TEXT,
    "goals" TEXT,
    "referralSnapshot" TEXT,
    "consentVersion" TEXT,
    "consentedAt" TIMESTAMP(3),
    "phoneVerifiedAt" TIMESTAMP(3),
    "status" TEXT NOT NULL DEFAULT 'DRAFT',
    "submittedAt" TIMESTAMP(3),
    "expiresAt" TIMESTAMP(3) NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "StartupPublicApplicant_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "StartupOtpChallenge" (
    "id" TEXT NOT NULL,
    "applicantId" TEXT NOT NULL,
    "mobile" TEXT NOT NULL,
    "otpHash" TEXT NOT NULL,
    "provider" TEXT NOT NULL,
    "providerRef" TEXT,
    "status" TEXT NOT NULL DEFAULT 'PENDING',
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "expiresAt" TIMESTAMP(3) NOT NULL,
    "consumedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "StartupOtpChallenge_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "StartupApplicationEvent" (
    "id" TEXT NOT NULL,
    "applicantId" TEXT NOT NULL,
    "actorUserId" TEXT,
    "action" TEXT NOT NULL,
    "reason" TEXT,
    "metadata" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "StartupApplicationEvent_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "StartupAdmissionAssignment" (
    "id" TEXT NOT NULL,
    "applicantId" TEXT NOT NULL,
    "assignedUserId" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'ACTIVE',
    "assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "endedAt" TIMESTAMP(3),
    CONSTRAINT "StartupAdmissionAssignment_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "StartupAdmissionFollowUp" (
    "id" TEXT NOT NULL,
    "applicantId" TEXT NOT NULL,
    "actorUserId" TEXT NOT NULL,
    "contactMethod" TEXT,
    "outcome" TEXT,
    "note" TEXT NOT NULL,
    "nextFollowUpAt" TIMESTAMP(3),
    "status" TEXT NOT NULL DEFAULT 'OPEN',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "StartupAdmissionFollowUp_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "StartupPublicApplicant_reference_key" ON "StartupPublicApplicant"("reference");
CREATE INDEX "StartupPublicApplicant_organizationId_status_createdAt_idx" ON "StartupPublicApplicant"("organizationId", "status", "createdAt");
CREATE INDEX "StartupPublicApplicant_normalizedMobile_expiresAt_idx" ON "StartupPublicApplicant"("normalizedMobile", "expiresAt");
CREATE INDEX "StartupPublicApplicant_expiresAt_idx" ON "StartupPublicApplicant"("expiresAt");
CREATE INDEX "StartupOtpChallenge_applicantId_status_createdAt_idx" ON "StartupOtpChallenge"("applicantId", "status", "createdAt");
CREATE INDEX "StartupOtpChallenge_expiresAt_idx" ON "StartupOtpChallenge"("expiresAt");
CREATE INDEX "StartupApplicationEvent_applicantId_createdAt_idx" ON "StartupApplicationEvent"("applicantId", "createdAt");
CREATE INDEX "StartupApplicationEvent_actorUserId_createdAt_idx" ON "StartupApplicationEvent"("actorUserId", "createdAt");
CREATE INDEX "StartupAdmissionAssignment_assignedUserId_status_assignedAt_idx" ON "StartupAdmissionAssignment"("assignedUserId", "status", "assignedAt");
CREATE INDEX "StartupAdmissionAssignment_applicantId_status_idx" ON "StartupAdmissionAssignment"("applicantId", "status");
CREATE INDEX "StartupAdmissionFollowUp_applicantId_createdAt_idx" ON "StartupAdmissionFollowUp"("applicantId", "createdAt");
CREATE INDEX "StartupAdmissionFollowUp_actorUserId_nextFollowUpAt_status_idx" ON "StartupAdmissionFollowUp"("actorUserId", "nextFollowUpAt", "status");
ALTER TABLE "StartupPublicApplicant" ADD CONSTRAINT "StartupPublicApplicant_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "StartupOtpChallenge" ADD CONSTRAINT "StartupOtpChallenge_applicantId_fkey" FOREIGN KEY ("applicantId") REFERENCES "StartupPublicApplicant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StartupApplicationEvent" ADD CONSTRAINT "StartupApplicationEvent_applicantId_fkey" FOREIGN KEY ("applicantId") REFERENCES "StartupPublicApplicant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "StartupAdmissionAssignment" ADD CONSTRAINT "StartupAdmissionAssignment_applicantId_fkey" FOREIGN KEY ("applicantId") REFERENCES "StartupPublicApplicant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "StartupAdmissionFollowUp" ADD CONSTRAINT "StartupAdmissionFollowUp_applicantId_fkey" FOREIGN KEY ("applicantId") REFERENCES "StartupPublicApplicant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
